// Full State Reconciliation Configuration
return {
  reconciliation_targets: [
    { path: 'task-cards/README.md', type: 'index', aggregation: 'count_by_status' },
    { path: 'task-cards/INDEX.md', type: 'index', aggregation: 'count_by_status' },
    { path: 'docs/CONSOLIDATED_ROADMAP.md', type: 'roadmap', aggregation: 'summarize_progress' }
  ],
  status_patterns: {
    task_status: /^\*?\*?Status:?\*?\*?\s*(.+)$/im,
    completion_pct: /(\d+)%\s*(?:complete|done|finished)/i,
    checkbox_checked: /- \[x\]/gi,
    checkbox_unchecked: /- \[ \]/gi,
    fraction: /(\d+)\/(\d+)\s*Complete/i,
    wave_status: /^##\s*Wave\s*\d+.*?Status:\s*(.+)$/im
  },
  status_mappings: {
    'complete': 'Complete', 'completed': 'Complete', '✅ complete': 'Complete', '✅ done': 'Complete', 'done': 'Complete',
    'in progress': 'In Progress', 'in-progress': 'In Progress', '🔄 in progress': 'In Progress', '🔄 active': 'In Progress',
    'not started': 'Not Started', 'ready': 'Not Started', '🟢 ready': 'Not Started',
    'blocked': 'Blocked', '🔴 blocked': 'Blocked', 'deferred': 'Deferred', '🟡 deferred': 'Deferred'
  },
  mismatch_tolerance_pct: 5,
  run_timestamp: new Date().toISOString()
};

const config = $('Workflow Configuration').first().json;
const tree = $input.first().json.tree || [];
const taskCards = tree
  .filter(item => item.type === 'blob' && item.path.startsWith('task-cards/') && item.path.endsWith('.md') && !item.path.includes('README.md') && !item.path.includes('INDEX.md'))
  .map(item => ({ path: item.path, sha: item.sha, directory: item.path.substring(0, item.path.lastIndexOf('/') + 1) || 'task-cards/' }));
return taskCards.map(card => ({ json: { config, card_path: card.path, card_sha: card.sha, directory: card.directory, total_cards: taskCards.length } }));

const batchItem = $('Process Each Task Card').first().json;
const config = batchItem.config;
const cardPath = batchItem.card_path;
const directory = batchItem.directory;
const fileData = $input.first().json;
let content = '';
if (fileData.content) { try { content = Buffer.from(fileData.content, 'base64').toString('utf8'); } catch (e) { content = ''; } }
let extractedStatus = 'Unknown';
let checkboxComplete = 0;
let checkboxTotal = 0;
if (content) {
  const statusMatch = content.match(/^\*?\*?Status:?\*?\*?\s*(.+)$/im);
  if (statusMatch) {
    let rawStatus = statusMatch[1].trim();
    const normalized = rawStatus.toLowerCase().replace(/[^\w\s]/g, '').trim();
    for (const [key, value] of Object.entries(config.status_mappings)) {
      if (normalized.includes(key.toLowerCase().replace(/[^\w\s]/g, ''))) { extractedStatus = value; break; }
    }
    if (extractedStatus === 'Unknown' && rawStatus.length < 30) { extractedStatus = rawStatus; }
  }
  const checkedMatches = content.match(/- \[x\]/gi);
  const uncheckedMatches = content.match(/- \[ \]/gi);
  checkboxComplete = checkedMatches ? checkedMatches.length : 0;
  checkboxTotal = checkboxComplete + (uncheckedMatches ? uncheckedMatches.length : 0);
}
return { card_path: cardPath, directory: directory, status: extractedStatus, is_complete: extractedStatus === 'Complete', checkbox_complete: checkboxComplete, checkbox_total: checkboxTotal, config: config };

const allResults = $input.all().map(item => item.json);
const config = allResults[0]?.config || $('Workflow Configuration').first().json;
const byDirectory = {};
for (const result of allResults) {
  const dir = result.directory || 'task-cards/';
  if (!byDirectory[dir]) { byDirectory[dir] = { cards: [], complete: 0, in_progress: 0, not_started: 0, blocked: 0, unknown: 0, total: 0 }; }
  byDirectory[dir].cards.push({ path: result.card_path, status: result.status });
  byDirectory[dir].total++;
  switch (result.status) {
    case 'Complete': byDirectory[dir].complete++; break;
    case 'In Progress': byDirectory[dir].in_progress++; break;
    case 'Not Started': byDirectory[dir].not_started++; break;
    case 'Blocked': byDirectory[dir].blocked++; break;
    default: byDirectory[dir].unknown++;
  }
}
let overall = { complete: 0, in_progress: 0, not_started: 0, blocked: 0, unknown: 0, total: 0 };
for (const dir of Object.values(byDirectory)) { overall.complete += dir.complete; overall.in_progress += dir.in_progress; overall.not_started += dir.not_started; overall.blocked += dir.blocked; overall.unknown += dir.unknown; overall.total += dir.total; }
return { source: 'task_cards', by_directory: byDirectory, overall: overall, overall_completion_pct: overall.total > 0 ? Math.round((overall.complete / overall.total) * 100) : 0, config: config, timestamp: new Date().toISOString() };

const config = $('Workflow Configuration').first().json;
const tree = $('List All Files').first().json.tree || [];
const statusReports = tree.filter(item => item.type === 'blob' && item.path.startsWith('docs/status-reports/') && item.path.endsWith('.md')).map(item => ({ path: item.path, sha: item.sha }));
if (statusReports.length === 0) { return { json: { config, reports: [], has_reports: false } }; }
return statusReports.map(report => ({ json: { config, report_path: report.path, report_sha: report.sha, total_reports: statusReports.length } }));

const batchItem = $('Process Each Report').first().json;
const config = batchItem.config;
const reportPath = batchItem.report_path;
const fileData = $input.first().json;
let content = '';
if (fileData.content) { try { content = Buffer.from(fileData.content, 'base64').toString('utf8'); } catch (e) { content = ''; } }
let summary = { path: reportPath, filename: reportPath.split('/').pop(), date: null, overall_status: 'Unknown', completion_pct: null, key_updates: [] };
if (content) {
  const dateMatch = reportPath.match(/(\d{4}-\d{2}-\d{2})/);
  if (dateMatch) summary.date = dateMatch[1];
  const statusMatch = content.match(/(?:Overall\s+)?Status:\s*(.+)/i);
  if (statusMatch) summary.overall_status = statusMatch[1].trim();
  const pctMatch = content.match(/(\d+)%\s*(?:complete|done|finished)/i);
  if (pctMatch) summary.completion_pct = parseInt(pctMatch[1]);
  const waveMatches = content.matchAll(/Wave\s*(\d+).*?(?:Status|:)\s*(.+)/gi);
  for (const match of waveMatches) { summary.key_updates.push({ wave: parseInt(match[1]), status: match[2].trim().substring(0, 50) }); }
}
return { report: summary, config: config };

const allResults = $input.all().map(item => item.json);
const config = allResults[0]?.config || $('Workflow Configuration').first().json;
const reports = allResults.filter(r => r.report).map(r => r.report).sort((a, b) => { if (a.date && b.date) return b.date.localeCompare(a.date); return 0; });
const latestReport = reports[0];
return { source: 'status_reports', reports: reports, latest: latestReport || null, report_count: reports.length, config: config, timestamp: new Date().toISOString() };

