if (taskCards && taskCards.by_directory) {
  for (const [dir, stats] of Object.entries(taskCards.by_directory)) {
    const dirName = dir.replace('task-cards/', '').replace(/\/$/, '') || 'root';
    const dirPattern = new RegExp(`${dirName}.*?(\\d+)/(\\d+)\\s*Complete`, 'i');
    const match = readmeContent.match(dirPattern);
    if (match) {
      const claimedComplete = parseInt(match[1]);
      const claimedTotal = parseInt(match[2]);
      if (claimedTotal !== stats.total) {
        mismatches.push({ type: 'FILE_COUNT_MISMATCH', severity: 'high', document: 'task-cards/README.md', directory: dir, description: `${dirName}: README claims ${claimedTotal} total files but directory has ${stats.total} files`, claimed: { total: claimedTotal }, actual: { total: stats.total }, action: `Update to ${stats.complete}/${stats.total} in ${dirName} section` });
      }
      if (claimedComplete !== stats.complete && claimedTotal === stats.total) {
        mismatches.push({ type: 'COMPLETION_COUNT_MISMATCH', severity: 'high', document: 'task-cards/README.md', directory: dir, description: `${dirName}: README claims ${claimedComplete} complete but ${stats.complete} are actually complete`, claimed: { complete: claimedComplete, total: claimedTotal }, actual: { complete: stats.complete, total: stats.total }, action: `Update to ${stats.complete}/${stats.total} in ${dirName} section` });
      }
    }
  }
}
if (taskCards) {
  const actualOverallPct = taskCards.overall_completion_pct;
  const readmePctMatch = readmeContent.match(/(?:Overall|Total).*?(\d+)%/i);
  if (readmePctMatch) {
    const claimedPct = parseInt(readmePctMatch[1]);
    if (Math.abs(claimedPct - actualOverallPct) > tolerance) {
