rawOutput = rawOutput.trim();
if (rawOutput.startsWith('```json')) { rawOutput = rawOutput.slice(7); }
if (rawOutput.startsWith('```')) { rawOutput = rawOutput.slice(3); }
if (rawOutput.endsWith('```')) { rawOutput = rawOutput.slice(0, -3); }
rawOutput = rawOutput.trim();
rawOutput = rawOutput.replace(/,(\s*[\]\}])/g, '$1');
try { const parsed = JSON.parse(rawOutput); return parsed; } catch (e) {
  const startIdx = rawOutput.indexOf('{');
  const endIdx = rawOutput.lastIndexOf('}');
  if (startIdx !== -1 && endIdx > startIdx) {
    let extracted = rawOutput.substring(startIdx, endIdx + 1);
    extracted = extracted.replace(/,(\s*[\]\}])/g, '$1');
    try { return JSON.parse(extracted); } catch (e2) { throw new Error('No valid JSON found in AI output: ' + rawOutput.substring(0, 300)); }
  }
  throw new Error('No valid JSON found in AI output: ' + rawOutput.substring(0, 300));
}

